    // %b: -ddddddddp±ddd
    gocpp::slice<unsigned char> fmtB(gocpp::slice<unsigned char> dst, bool neg, uint64_t mant, int exp)
    {
        if(neg)
        {
            dst = append(dst, '-');
        }
        dst = AppendUint(dst, mant, 10);
        dst = append(dst, 'p');
        if(exp >= 0)
        {
            dst = append(dst, '+');
        }
        dst = AppendInt(dst, int64_t(exp), 10);
        return dst;
    }

    // %x: -0x1.yyyyyyyyp±ddd or -0x0p+0. (y is hex digit, d is decimal digit)
    gocpp::slice<unsigned char> fmtX(gocpp::slice<unsigned char> dst, int prec, unsigned char fmt, bool neg, uint64_t mant, int exp, int mantBits)
    {
        if(mant == 0)
        {
            exp = 0;
        }

        // Shift digits so leading 1 (if any) is at bit 1<<60.
        // TODO: Is this the right way to handle subnormals?
        mant <<= 60 - mantBits;
        for(; mant != 0 && mant & (1 << 60) == 0; )
        {
            mant <<= 1;
            exp--;
        }

        // Round if requested.
        if(prec >= 0 && prec < 15)
        {
            auto shift = (unsigned int)(prec * 4);
            auto extra = (mant << shift) & ((1 << 60) - 1);
            mant >>= 60 - shift;
            if(extra | (mant & 1) > (1 << 59))
            {
                mant++;
            }
            mant <<= 60 - shift;
            if(mant & (1 << 61) != 0)
            {
                // Wrapped around.
                mant >>= 1;
                exp++;
            }
        }

        auto hex = lowerhex;
        if(fmt == 'X')
        {
            hex = upperhex;
        }

        // sign, 0x, leading digit
        if(neg)
        {
            dst = append(dst, '-');
        }
        dst = append(dst, '0', fmt, '0' + (unsigned char)((mant >> 60) & 1));

        // .fraction
        // remove leading 0 or 1
        mant <<= 4;
        if(prec < 0 && mant != 0)
        {
            dst = append(dst, '.');
            for(; mant != 0; )
            {
                dst = append(dst, hex[(mant >> 60) & 15]);
                mant <<= 4;
            }
        }
        else
        if(prec > 0)
        {
            dst = append(dst, '.');
            for(auto i = 0; i < prec; i++)
            {
                dst = append(dst, hex[(mant >> 60) & 15]);
                mant <<= 4;
            }
        }

        // p±
        auto ch = (unsigned char)('P');
        if(fmt == lower(fmt))
        {
            ch = 'p';
        }
        dst = append(dst, ch);
        if(exp < 0)
        {
            ch = '-';
            exp = - exp;
        }
        else
        {
            ch = '+';
        }
        dst = append(dst, ch);

        // dd or ddd or dddd
        //Go switch emulation
        {
            int conditionId = -1;
            if(exp < 100) { conditionId = 0; }
            else if(exp < 1000) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    dst = append(dst, (unsigned char)(exp / 10) + '0', (unsigned char)(exp % 10) + '0');
                    break;
                case 1:
                    dst = append(dst, (unsigned char)(exp / 100) + '0', (unsigned char)((exp / 10) % 10) + '0', (unsigned char)(exp % 10) + '0');
                    break;
                default:
                    dst = append(dst, (unsigned char)(exp / 1000) + '0', (unsigned char)(exp / 100) % 10 + '0', (unsigned char)((exp / 10) % 10) + '0', (unsigned char)(exp % 10) + '0');
                    break;
            }
        }

        return dst;
    }

